using UnityEngine;

namespace OpenSkies.World
{
    /// <summary>
    /// Builds the environment reflections from the sky once the scene starts, so
    /// the paint, the glass and the sea reflect the sky without a lighting bake
    /// (the scene is generated by code and has no baked lighting data). One call
    /// on start, nothing per frame.
    /// </summary>
    public sealed class EnvironmentLighting : MonoBehaviour
    {
        [Tooltip("Strength of the sky reflections on glossy surfaces.")]
        [Range(0f, 1f)] public float reflectionIntensity = 0.85f;

        public bool Updated { get; private set; }

        void Start() => Refresh();

        /// <summary>Regenerates the reflection cubemap from the current skybox (a few milliseconds, once).</summary>
        public void Refresh()
        {
            try
            {
                RenderSettings.defaultReflectionMode = UnityEngine.Rendering.DefaultReflectionMode.Skybox;
                RenderSettings.reflectionIntensity = reflectionIntensity;
                DynamicGI.UpdateEnvironment();
                Updated = true;
            }
            catch (System.Exception e)
            {
                // Reflections are a nicety: never let them stop the scene from starting.
                Debug.LogWarning($"[OpenSkies] Environment reflections not updated: {e.Message}");
            }
        }
    }
}
